ALTER TABLE public.issue_notifications ADD COLUMN recipient_user_id uuid, ADD COLUMN event_id uuid REFERENCES public.issue_events(id), ADD COLUMN event_key text, ADD COLUMN notification_type text NOT NULL DEFAULT 'system', ADD COLUMN title text NOT NULL DEFAULT 'Case update', ADD COLUMN priority text NOT NULL DEFAULT 'normal', ADD COLUMN actor_id uuid;
ALTER TABLE public.issue_notifications ALTER COLUMN issue_id DROP NOT NULL;
ALTER TABLE public.notification_reads ALTER COLUMN read_at DROP NOT NULL;
ALTER TABLE public.notification_reads ADD COLUMN archived_at timestamptz;
ALTER TABLE public.issue_events ADD COLUMN visibility text NOT NULL DEFAULT 'public';
CREATE UNIQUE INDEX notification_recipient_event ON public.issue_notifications(recipient_user_id,event_key) WHERE recipient_user_id IS NOT NULL;
CREATE INDEX notifications_recipient_created ON public.issue_notifications(recipient_user_id,created_at DESC);
CREATE INDEX reads_recipient_state ON public.notification_reads(user_id,read_at,archived_at);
CREATE INDEX events_case_kind ON public.issue_events(issue_id,kind,created_at);
CREATE OR REPLACE FUNCTION public.notification_access(_recipient uuid,_issue uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid()=_recipient AND public.is_staff(auth.uid()) AND (_issue IS NULL OR public.staff_can_work(auth.uid(),_issue)) $$;
REVOKE ALL ON FUNCTION public.notification_access(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.notification_access(uuid,uuid) TO authenticated;
ALTER POLICY "staff read notifications" ON public.issue_notifications USING(public.notification_access(recipient_user_id,issue_id));
ALTER POLICY "own notification reads" ON public.notification_reads USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.issue_notifications n WHERE n.id=notification_id AND public.notification_access(n.recipient_user_id,n.issue_id)));
ALTER POLICY "authorized notification mark" ON public.notification_reads WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.issue_notifications n WHERE n.id=notification_id AND public.notification_access(n.recipient_user_id,n.issue_id)));
REVOKE INSERT ON public.notification_reads FROM authenticated;
CREATE OR REPLACE FUNCTION public.set_notification_state(_id uuid,_action text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN
 IF NOT public.is_staff(auth.uid()) OR _action NOT IN ('read','unread','archive','restore','read_all') THEN RAISE EXCEPTION 'Notification action not permitted'; END IF;
 IF _action='read_all' THEN
 IF _id IS NOT NULL THEN RAISE EXCEPTION 'Invalid bulk action'; END IF;
 INSERT INTO public.notification_reads(notification_id,user_id,read_at) SELECT t.id,auth.uid(),now() FROM public.issue_notifications t LEFT JOIN public.notification_reads r ON r.notification_id=t.id AND r.user_id=auth.uid() WHERE public.notification_access(t.recipient_user_id,t.issue_id) AND r.read_at IS NULL AND r.archived_at IS NULL ON CONFLICT(notification_id,user_id) DO UPDATE SET read_at=coalesce(notification_reads.read_at,excluded.read_at);
 GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END IF;
 PERFORM id FROM public.issue_notifications WHERE id=_id AND public.notification_access(recipient_user_id,issue_id) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Notification unavailable'; END IF;
 INSERT INTO public.notification_reads(notification_id,user_id,read_at,archived_at) VALUES(_id,auth.uid(),CASE WHEN _action='read' THEN now() END,CASE WHEN _action='archive' THEN now() END) ON CONFLICT(notification_id,user_id) DO UPDATE SET read_at=CASE WHEN _action='read' THEN coalesce(notification_reads.read_at,now()) WHEN _action='unread' THEN NULL ELSE notification_reads.read_at END,archived_at=CASE WHEN _action='archive' THEN coalesce(notification_reads.archived_at,now()) WHEN _action='restore' THEN NULL ELSE notification_reads.archived_at END;
 RETURN 1; END $$;
REVOKE ALL ON FUNCTION public.set_notification_state(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_notification_state(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.notification_page(_state text DEFAULT 'all',_type text DEFAULT '',_priority text DEFAULT '',_search text DEFAULT '',_page integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN
 IF NOT public.is_staff(auth.uid()) OR _state NOT IN ('all','unread','read','archived') OR _page NOT BETWEEN 0 AND 10000 OR length(_search)>120 THEN RAISE EXCEPTION 'Invalid notification request'; END IF;
 WITH eligible AS(SELECT n.id,n.issue_id,n.notification_type,n.title,n.detail,n.priority,n.created_at,n.channel,n.status,r.read_at,r.archived_at,i.ref_code FROM public.issue_notifications n LEFT JOIN public.notification_reads r ON r.notification_id=n.id AND r.user_id=auth.uid() LEFT JOIN public.issues i ON i.id=n.issue_id WHERE public.notification_access(n.recipient_user_id,n.issue_id)), filtered AS(SELECT * FROM eligible WHERE CASE _state WHEN 'archived' THEN archived_at IS NOT NULL WHEN 'unread' THEN read_at IS NULL AND archived_at IS NULL WHEN 'read' THEN read_at IS NOT NULL AND archived_at IS NULL ELSE archived_at IS NULL END AND (_type='' OR notification_type=_type) AND (_priority='' OR priority=_priority) AND (_search='' OR title ILIKE '%'||_search||'%' OR detail ILIKE '%'||_search||'%' OR ref_code ILIKE '%'||_search||'%')) SELECT jsonb_build_object('unread',(SELECT count(*) FROM eligible WHERE read_at IS NULL AND archived_at IS NULL),'total',(SELECT count(*) FROM filtered),'rows',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM(SELECT * FROM filtered ORDER BY created_at DESC,id DESC LIMIT 25 OFFSET _page*25)s),'[]'::jsonb)) INTO result; RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.notification_page(text,text,text,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.notification_page(text,text,text,text,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.emit_case_notifications(_event uuid,_type text,_title text,_detail text,_supervisor_only boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.issue_events; BEGIN
 SELECT * INTO e FROM public.issue_events WHERE id=_event; IF e.id IS NULL THEN RAISE EXCEPTION 'Event required'; END IF;
 INSERT INTO public.issue_notifications(issue_id,audience,channel,status,detail,attempts,recipient_user_id,event_id,event_key,notification_type,title,priority,actor_id) SELECT e.issue_id,'staff','in_app','posted',left(_detail,500),1,p.user_id,e.id,e.id::text||':'||_type,_type,_title,CASE WHEN _type IN ('deadline_breached','escalation') THEN 'high' ELSE 'normal' END,e.actor_id FROM public.staff_profiles p WHERE public.staff_can_work(p.user_id,e.issue_id) AND (NOT _supervisor_only OR public.is_supervisor(p.user_id)) ON CONFLICT(recipient_user_id,event_key) WHERE recipient_user_id IS NOT NULL DO NOTHING;
END $$;
REVOKE ALL ON FUNCTION public.emit_case_notifications(uuid,text,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.emit_case_notifications(uuid,text,text,text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.record_issue_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE typ text; ttl text; BEGIN
 IF NEW.visibility='internal' AND NEW.kind<>'supervisor_instruction' THEN RETURN NEW; END IF;
 typ:=CASE WHEN NEW.kind='created' THEN 'new_report' WHEN NEW.kind='routing' THEN CASE WHEN EXISTS(SELECT 1 FROM public.issues WHERE id=NEW.issue_id AND assignment_state='routing_exception') THEN 'routing_exception' ELSE 'new_report' END WHEN NEW.kind LIKE 'assignment%' THEN 'assignment' WHEN NEW.kind='acknowledged' THEN 'acknowledged' WHEN NEW.kind IN ('escalated','ack_escalated') THEN 'escalation' WHEN NEW.kind='ack_overdue' THEN 'deadline_breached' WHEN NEW.kind='deadline_approaching' THEN 'deadline_approaching' WHEN NEW.kind='citizen_confirmed' THEN 'resolution_confirmed' WHEN NEW.kind IN ('disputed','citizen_reopened') THEN 'case_reopened' WHEN NEW.kind='evidence_completion' OR NEW.to_status IN ('awaiting_verification','resolved') THEN 'resolution_submitted' WHEN NEW.kind='supervisor_instruction' THEN 'supervisor_instruction' WHEN NEW.kind IN ('status_change','eta_changed','public_update') THEN 'public_update' ELSE NULL END;
 IF typ IS NOT NULL THEN ttl:=initcap(replace(typ,'_',' ')); PERFORM public.emit_case_notifications(NEW.id,typ,ttl,CASE WHEN typ='supervisor_instruction' THEN NEW.note ELSE ttl||' for a case in your authorized workload.' END,typ='routing_exception');
 IF NEW.kind IN ('created','routing') AND EXISTS(SELECT 1 FROM public.issues WHERE id=NEW.issue_id AND acknowledged_at IS NULL AND ack_due_at IS NOT NULL AND assignment_state<>'routing_exception') THEN PERFORM public.emit_case_notifications(NEW.id,'acknowledgement_required','Acknowledgement required','Response required within the configured Siddi target.',false); END IF; END IF;
 IF NEW.kind='created' THEN INSERT INTO public.issue_notifications(issue_id,audience,channel,status,detail,event_id,event_key) VALUES(NEW.issue_id,'authority','none','not_configured','No external government channel is configured; no delivery occurred.',NEW.id,NEW.id::text||':external'); END IF;
 IF NEW.visibility='public' AND NEW.kind IN ('acknowledged','eta_changed','status_change','public_update','evidence_completion') THEN INSERT INTO public.issue_notifications(issue_id,audience,channel,status,detail,attempts,event_id,event_key) VALUES(NEW.issue_id,'citizen','in_app','posted','Saved case update available in tracking.',1,NEW.id,NEW.id::text||':citizen'); END IF; RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.account_notification_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.table_name IN ('staff_accounts','administrator_accounts') AND NEW.action IN ('scope_changed','team_scope_changed','suspend','reactivate','role_changed','recovery_requested','invited') THEN INSERT INTO public.issue_notifications(audience,channel,status,detail,attempts,recipient_user_id,event_key,notification_type,title,actor_id) VALUES('staff','in_app','posted','Your account access was updated. Review your authorized scope or contact your administrator.',1,NEW.record_id,'audit:'||NEW.id::text,'system','Account access updated',NEW.actor_id) ON CONFLICT(recipient_user_id,event_key) WHERE recipient_user_id IS NOT NULL DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.account_notification_event() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER account_notification AFTER INSERT ON public.civic_directory_audit FOR EACH ROW EXECUTE FUNCTION public.account_notification_event();
CREATE OR REPLACE FUNCTION public.notify_released_handler() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF OLD.assigned_to IS NOT NULL AND OLD.assigned_to IS DISTINCT FROM NEW.assigned_to THEN INSERT INTO public.issue_notifications(audience,channel,status,detail,attempts,recipient_user_id,event_key,notification_type,title) VALUES('staff','in_app','posted','An earlier assignment was removed from your workload. Current permissions apply to all case links.',1,OLD.assigned_to,'release:'||NEW.id::text||':'||gen_random_uuid()::text,'reassignment','Assignment changed'); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.notify_released_handler() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER released_handler_notification AFTER UPDATE OF assigned_to ON public.issues FOR EACH ROW EXECUTE FUNCTION public.notify_released_handler();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(p.oid) INTO d FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='public_case_events'; d:=replace(d,'WHEN kind=''status_change''','WHEN kind IN (''status_change'',''public_update'')'); d:=replace(d,'WHERE issue_id=_id','WHERE issue_id=_id AND visibility=''public'''); EXECUTE d; END $$;